using IndieRun;
using System.IO;
using System.Reflection;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Markup;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;
using System.Xml.Linq;
class Program
{
    static void Check(bool ok,string text){if(!ok)throw new Exception(text);}
    static void Set(object o,string field,object? value)=>o.GetType().GetField(field,BindingFlags.NonPublic|BindingFlags.Instance)!.SetValue(o,value);
    static T Get<T>(object o,string field)=>(T)o.GetType().GetField(field,BindingFlags.NonPublic|BindingFlags.Instance)!.GetValue(o)!;
    static object? Call(object o,string method,params object?[] args)=>o.GetType().GetMethod(method,BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.DeclaredOnly)!.Invoke(o,args);
    static Package Fixture(string dir,bool selective=false)
    {
        var folder=Path.Combine(dir,"input","GeneratedGame");Directory.CreateDirectory(Path.Combine(folder,"Data"));Directory.CreateDirectory(Path.Combine(folder,"Extras"));
        File.WriteAllText(Path.Combine(folder,"Game.exe"),"harmless generated fixture; never execute");File.WriteAllBytes(Path.Combine(folder,"Data","large.bin"),Enumerable.Range(0,1536*1024).Select(i=>(byte)(i%251)).ToArray());File.WriteAllText(Path.Combine(folder,"Extras","guide.txt"),"kept or moved according to selection");
        var p=new Package{Id=Guid.NewGuid().ToString("N"),IsReal=true,Registered=false,Source=folder,DetectedRoot=folder,SearchRoot=Path.Combine(dir,"input"),Name="GeneratedGame",Folder="GeneratedGame",Alias="가상 게임"};if(selective)p.OmittedFolders.Add("Extras");return p;
    }
    static MainWindow Window(string dir,out Package p)
    {
        p=Fixture(dir);var scan=GameScanner.Scan(p.SearchRoot);scan.PrepareIndex();var plan=new WorkspaceDocument{SearchRoot=p.SearchRoot,SearchLocations=[new(){Path=p.SearchRoot}],Destination=Path.Combine(dir,"library"),BackupRoot=Path.Combine(dir,"backups"),Packages=[p],Checkpoints=[WorkspaceReconciler.Capture(p,scan)]};var store=new WorkspaceStore(Path.Combine(dir,"data","workspace.json"));store.Save(plan);
        var w=new MainWindow();new System.Windows.Interop.WindowInteropHelper(w).EnsureHandle();Set(w,"workspaceStore",store);Set(w,"workspaceLock",store.AcquireLock());Call(w,"ApplyWorkspace",plan);Set(w,"snapshot",scan);Set(w,"sessionReady",true);Set(w,"playerRoot",plan.Destination);Set(w,"playerDocument",new PlayerDocument());Set(w,"directEngineFactory",(Func<BackupEngine>)(()=>new(Path.Combine(dir,"records"))));return w;
    }
    static void Close(MainWindow w){Set(w,"closingWithoutSave",true);w.Close();}
    static IEnumerable<DependencyObject> Logical(DependencyObject root){yield return root;foreach(var child in LogicalTreeHelper.GetChildren(root).OfType<DependencyObject>())foreach(var nested in Logical(child))yield return nested;}
    static void Wait(Task task){var frame=new DispatcherFrame();task.ContinueWith(_=>Application.Current.Dispatcher.BeginInvoke(new Action(()=>frame.Continue=false)));Dispatcher.PushFrame(frame);task.GetAwaiter().GetResult();}
    static void Click(Button b)=>b.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
    static void Toggle(System.Windows.Controls.Primitives.ToggleButton b,bool value){b.IsChecked=value;b.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}
    static Button FindButton(Window w,string text)=>Logical((DependencyObject)w.Content).OfType<Button>().Single(b=>b.Content as string==text);
    static T Named<T>(Window w,string name)where T:FrameworkElement=>Logical((DependencyObject)w.Content).OfType<T>().Single(e=>e.Name==name);
    static void Layout(Window w,double width,double height,string file){var body=(FrameworkElement)w.Content;body.Measure(new Size(width,height));body.Arrange(new Rect(0,0,width,height));body.UpdateLayout();foreach(var b in Logical(body).OfType<Button>().Where(b=>b.IsVisible||b.ActualWidth>0)){var point=b.TranslatePoint(new Point(),body);Check(point.X>=-1&&point.X+b.ActualWidth<=width+1,"Button clipped horizontally: "+b.Content);}var bitmap=new RenderTargetBitmap((int)width,(int)height,96,96,PixelFormats.Pbgra32);var bg=new DrawingVisual();using(var draw=bg.RenderOpen())draw.DrawRectangle(w.Background,null,new Rect(0,0,width,height));bitmap.Render(bg);bitmap.Render(body);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using var output=File.Create(file);png.Save(output);}
    static Package Second(MainWindow w,string dir){var p=Fixture(Path.Combine(dir,"second"));p.Alias="두 번째 가상 게임";Get<List<Package>>(w,"packages").Add(p);var scan=GameScanner.Scan(dir);Set(w,"snapshot",scan);Set(w,"checkpoints",Get<List<Package>>(w,"packages").Select(g=>WorkspaceReconciler.Capture(g,scan)).ToList());return p;}
    static IntakeSelection Plan(MainWindow w,List<Package> games)=>new(new MoveSelection(games,Get<List<Package>>(w,"packages")));
    static LibraryDocument Registered(Package p)=>new(){Games=[new(){Id=p.Id,Folder=p.Folder,LastKnownPath=p.Source,Executables=["Game.exe"]}]};
    static (Package Game,string Parent,string Search,ScanSnapshot Scan,FolderCheckpoint Checkpoint) Game(string dir,bool marked=true)
    {
        var search=Path.Combine(dir,"container");var parent=Path.Combine(search,"外側パッケージ","ゲーム名");var data=Path.Combine(parent,"data");Directory.CreateDirectory(data);File.WriteAllText(Path.Combine(data,"Game.exe"),"harmless generated fixture; never execute");File.WriteAllText(Path.Combine(data,"save.dat"),"test save");
        var p=new Package{Id=Guid.NewGuid().ToString("N"),IsReal=true,Registered=marked,Source=data,DetectedRoot=data,SearchRoot=search,Name="data",Folder="data"};if(marked)LibraryStore.EnsureIdentity(data,p.Id);var scan=GameScanner.Scan(search);scan.SearchRoots.Add(search);scan.PrepareIndex();return(p,parent,search,scan,WorkspaceReconciler.Capture(p,scan));
    }
    static string RenameParent(string parent){var renamed=Path.Combine(Path.GetDirectoryName(parent)!,"ゲーム名5555");Directory.Move(parent,renamed);return Path.Combine(renamed,"data");}
    static string Refusal(Action run){try{run();}catch(IOException e){return e.Message;}throw new Exception("Expected refusal");}

    sealed record FamilyData(Package Parent,Package Child,string Search,string Library,ScanSnapshot Scan,List<FolderCheckpoint> Checks,LibraryDocument Document);
    static Package Model(string path,string search)=>new(){Id=Guid.NewGuid().ToString("N"),IsReal=true,Registered=true,Source=path,DetectedRoot=path,SearchRoot=search,Folder=Path.GetFileName(path),Name=Path.GetFileName(path)};
    static FamilyData Family(string dir)
    {
        var search=Path.Combine(dir,"Input");var parent=Path.Combine(search,"Outer","Bundle");var child=Path.Combine(parent,"engine");Directory.CreateDirectory(child);File.WriteAllText(Path.Combine(parent,"Main.exe"),"generated parent executable metadata");File.WriteAllText(Path.Combine(child,"Engine.exe"),"generated nested executable metadata");File.WriteAllText(Path.Combine(child,"required.dat"),"required generated data");var p=Model(parent,search);p.Alias="가상 본편";var c=Model(child,search);c.Alias="가상 하위 항목";c.Genres=["가상 장르"];LibraryStore.EnsureIdentity(parent,p.Id);LibraryStore.EnsureIdentity(child,c.Id);var library=Path.Combine(dir,"library");var doc=new LibraryDocument{Games=[new(){Id=p.Id,Folder=p.Folder,LastKnownPath=p.Source,Alias=p.Alias,Executables=["Main.exe"]},new(){Id=c.Id,Folder=c.Folder,LastKnownPath=c.Source,Alias=c.Alias,Genres=[..c.Genres],Executables=["Engine.exe"]}]};foreach(var g in doc.Games)g.Scope=StoredScope.Capture(g.Id==p.Id?p:c);new LibraryStore(library).Update(d=>d.Games=doc.Games);var scan=GameScanner.Scan(search);scan.SearchRoots.Add(search);return new(p,c,search,library,scan,[WorkspaceReconciler.Capture(p,scan),WorkspaceReconciler.Capture(c,scan)],doc);
    }
    static WorkspaceDocument Plan(FamilyData f)=>new(){SearchRoot=f.Search,SearchLocations=[new(){Path=f.Search}],Destination=f.Library,Packages=[f.Parent,f.Child],Checkpoints=f.Checks};
    static string Rename(FamilyData f){var next=Path.Combine(Path.GetDirectoryName(f.Parent.Source)!,"RenamedBundle");Directory.Move(f.Parent.Source,next);return next;}
    static ScanSnapshot Scan(string root){var s=GameScanner.Scan(root);s.SearchRoots.Add(root);s.PrepareIndex();return s;}
    static void ExplicitKeep(FamilyData f){var keep=Path.Combine(f.Parent.Source,"KeepHere");Directory.CreateDirectory(keep);File.WriteAllText(Path.Combine(keep,"keep.txt"),"must remain outside move");f.Parent.OmittedFolders.Add("KeepHere");f.Parent.Contents.Add(new(){Id=Guid.NewGuid().ToString("N"),Path="KeepHere",Role="exclude"});}
    [STAThread]static int Main(string[] args)
    {
        var root=Path.Combine(Path.GetFullPath(args[0]),"run-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var results=new List<object>();int failed=0;
        void Test(string name,Action<string> action){try{var dir=Path.Combine(root,name);Directory.CreateDirectory(dir);action(dir);results.Add(new{name,passed=true});Console.WriteLine("PASS "+name);}catch(Exception ex){failed++;results.Add(new{name,passed=false,error=ex.ToString()});Console.WriteLine("FAIL "+name+" "+ex.Message);}}
        Test("family-auto-rebind-updates-both-registered-entries",dir=>{var f=Family(dir);var next=Rename(f);var scan=Scan(f.Search);var games=new List<Package>{f.Parent,f.Child};IdentityReconciler.Rebind(games,f.Checks,f.Document,LibraryStore.Inspect(scan),scan,f.Library);Check(f.Parent.Source==next&&f.Child.Source==Path.Combine(next,"engine")&&f.Child.Alias=="가상 하위 항목"&&f.Child.Genres.Count==1,"Family or metadata not preserved");});
        Test("family-auto-rebind-reversed-order",dir=>{var f=Family(dir);var next=Rename(f);var scan=Scan(f.Search);IdentityReconciler.Rebind(new(){f.Child,f.Parent},f.Checks,f.Document,LibraryStore.Inspect(scan),scan,f.Library);Check(f.Parent.Source==next&&f.Child.Source==Path.Combine(next,"engine"),"Order dependent");});
        Test("family-manual-reconnect-keeps-relative-positions",dir=>{var f=Family(dir);var next=Rename(f);var plan=ReconnectPlanner.Prepare(Plan(f),f.Parent.Id,next,Scan(next),f.Document,new());Check(plan.Packages.Single(p=>p.Id==f.Parent.Id).Source==next&&plan.Packages.Single(p=>p.Id==f.Child.Id).Source==Path.Combine(next,"engine"),"Manual reconnect incomplete");Check(f.Parent.Source!=next,"Preparation mutated live input");});
        Test("family-rebuild-keeps-both-launch-entries",dir=>{var f=Family(dir);var result=ScanPreparation.Build(Scan(f.Search),[],[],[],f.Library,CancellationToken.None);Check(result.Packages.Any(p=>p.Id==f.Parent.Id)&&result.Packages.Any(p=>p.Id==f.Child.Id),"Child entry dropped");});
        Test("family-rebind-rejects-new-foreign-marker",dir=>{var f=Family(dir);var next=Rename(f);var foreign=Path.Combine(next,"unknown");Directory.CreateDirectory(foreign);LibraryStore.EnsureIdentity(foreign,Guid.NewGuid().ToString("N"));var scan=Scan(f.Search);IdentityReconciler.Rebind(new(){f.Parent,f.Child},f.Checks,f.Document,LibraryStore.Inspect(scan),scan,f.Library);Check(f.Parent.Source!=next,"Unknown identity absorbed");});
        Test("family-missing-child-marker-requires-confirmation",dir=>{var f=Family(dir);var next=Rename(f);File.Delete(Path.Combine(next,"engine",LibraryStore.MarkerName));var scan=Scan(f.Search);var games=new List<Package>{f.Parent,f.Child};IdentityReconciler.Rebind(games,f.Checks,f.Document,LibraryStore.Inspect(scan),scan,f.Library);Check(f.Parent.Source==next&&f.Child.Source==Path.Combine(next,"engine")&&!File.Exists(Path.Combine(next,"engine",LibraryStore.MarkerName)),"Missing marker silently recreated");IdentityReconciler.Flag(f.Child,LibraryStore.Inspect(scan),f.Document);Check(f.Child.ReviewState=="identity","Missing marker not flagged");});
        Test("library-preserves-exclusion-and-backup-respects-it",dir=>{var f=Family(dir);ExplicitKeep(f);new LibraryStore(f.Library).Register(f.Parent,[],Scan(f.Search));var result=ScanPreparation.Build(Scan(f.Search),[],[],[],f.Library,CancellationToken.None);var p=result.Packages.Single(p=>p.Id==f.Parent.Id);Check(!p.ScopeReviewRequired&&!p.Includes(Path.Combine(p.Source,"KeepHere"))&&p.Contents.Any(c=>c.Role=="exclude"),"Stored scope lost");var job=new BackupEngine(Path.Combine(dir,"backup")).CreateAsync(p,[]).GetAwaiter().GetResult();Check(!job.Files.Any(f=>f.RelativePath.Contains("keep.txt"))&&job.Files.Any(f=>f.RelativePath.Contains("required.dat")),"Backup scope differs");});
        Test("portable-preserves-exclusion",dir=>{var f=Family(dir);ExplicitKeep(f);PortableStore.Export(Path.GetDirectoryName(f.Parent.Source)!,f.Parent.Folder,f.Parent,new(){Id=f.Parent.Id},new(),f.Library);var record=PortableStore.Read(f.Parent.Source)!;var imported=Model(f.Parent.Source,f.Search);imported.Id=f.Parent.Id;PortableStore.Import(record,imported,new(),Path.Combine(dir,"settings"));Check(!imported.ScopeReviewRequired&&!imported.Includes(Path.Combine(imported.Source,"KeepHere"))&&imported.Contents.Any(c=>c.Role=="exclude"),"Portable exclusion lost");});
        Test("legacy-library-scope-blocks-backup",dir=>{var f=Family(dir);new LibraryStore(f.Library).Update(d=>{foreach(var g in d.Games)g.Scope=null;});var result=ScanPreparation.Build(Scan(f.Search),[],[],[],f.Library,CancellationToken.None);var p=result.Packages.Single(p=>p.Id==f.Parent.Id);Check(p.ScopeReviewRequired&&p.ReviewState=="scope","Unknown old scope not flagged");var target=Path.Combine(dir,"backup");Refusal(()=>new BackupEngine(target).CreateAsync(p,[]).GetAwaiter().GetResult());Check(!Directory.Exists(target)||!Directory.EnumerateFiles(target,"*",SearchOption.AllDirectories).Any(),"Unknown scope wrote backup");});
        Test("legacy-portable-scope-remains-unconfirmed",dir=>{var f=Family(dir);PortableStore.Export(Path.GetDirectoryName(f.Parent.Source)!,f.Parent.Folder,f.Parent,new(){Id=f.Parent.Id},new(),f.Library);var record=PortableStore.Read(f.Parent.Source)!;record.Scope=null;var p=Model(f.Parent.Source,f.Search);p.Id=f.Parent.Id;PortableStore.Import(record,p,new(),Path.Combine(dir,"settings"));Check(p.ScopeReviewRequired,"Legacy treated as include-all");});
        Test("malformed-scope-rejected",dir=>{bool refused=false;try{StoredScope.Validate(new(){OmittedFolders=["../escape"]});}catch(InvalidDataException){refused=true;}Check(refused,"Escaped scope accepted");});
        Test("same-size-time-different-bytes-never-change-executable",dir=>{var game=Path.Combine(dir,"Game");var old=Path.Combine(game,"engine");Directory.CreateDirectory(old);var exe=Path.Combine(old,"Game.exe");File.WriteAllText(exe,"AAAAAAAA");var p=Model(game,dir);p.DetectedRoot=old;var checkpoint=WorkspaceReconciler.Capture(p,Scan(game));var stamp=File.GetLastWriteTimeUtc(exe);Directory.Move(old,Path.Combine(dir,"archived"));var next=Path.Combine(game,"new-engine");Directory.CreateDirectory(next);File.WriteAllText(Path.Combine(next,"Game.exe"),"BBBBBBBB");File.SetLastWriteTimeUtc(Path.Combine(next,"Game.exe"),stamp);var g=new GamePlay{Id=p.Id,Executable=Path.Combine("engine","Game.exe"),WorkingDirectory="engine"};LaunchPathRepair.Apply([p],[checkpoint],new(){Games=[g]},Scan(game));Check(g.Executable==Path.Combine("engine","Game.exe")&&g.WorkingDirectory=="engine"&&p.ReviewState=="launch","Weak metadata changed executable");});
        Test("existing-child-scope-expand-and-commit",dir=>{var f=Family(dir);var parent=Path.GetDirectoryName(f.Parent.Source)!;Check(ScopeChange.Problem(f.Parent,parent,[f.Parent,f.Child],f.Scan)==null,"Known child blocks expansion");var service=new ScopeChange(Path.Combine(dir,"data"));var record=service.Prepare(Plan(f),new(),new(),f.Document,f.Parent.Id,parent);service.Commit(record);var saved=new WorkspaceStore(Path.Combine(dir,"data","workspace.json")).Load().Document!;Check(saved.Packages.Single(p=>p.Id==f.Parent.Id).Source==parent&&saved.Packages.Single(p=>p.Id==f.Child.Id).Source==f.Child.Source&&LibraryStore.ReadIdentity(f.Child.Source)?.GameId==f.Child.Id,"Scope commit disturbed family");});
        Test("scope-expand-recovery-after-new-marker",dir=>{var f=Family(dir);var data=Path.Combine(dir,"data");var service=new ScopeChange(data);var record=service.Prepare(Plan(f),new(),new(),f.Document,f.Parent.Id,Path.GetDirectoryName(f.Parent.Source)!);service.Checkpoint=phase=>{if(phase=="new-marker")throw new IOException("generated interruption");};Refusal(()=>service.Commit(record));Check(service.HasPending,"Recovery intent missing");Check(new ScopeChange(data).Recover()&&!new ScopeChange(data).HasPending&&LibraryStore.ReadIdentity(f.Child.Source)?.GameId==f.Child.Id,"Recovery failed");});
        Test("new-outside-child-still-blocks-scope-expansion",dir=>{var f=Family(dir);var sibling=Path.Combine(Path.GetDirectoryName(f.Parent.Source)!,"Other");Directory.CreateDirectory(sibling);var q=Model(sibling,f.Search);LibraryStore.EnsureIdentity(sibling,q.Id);Check(ScopeChange.Problem(f.Parent,Path.GetDirectoryName(f.Parent.Source)!,[f.Parent,f.Child,q],Scan(f.Search))!=null,"New outsider accepted");});
        Test("corrupt-child-marker-refuses-without-crash",dir=>{var f=Family(dir);File.WriteAllText(Path.Combine(f.Child.Source,LibraryStore.MarkerName),"broken");Check(!RegisteredTree.ExistingChild(f.Parent,f.Child,f.Parent.Source,Path.GetDirectoryName(f.Parent.Source)!),"Corrupt marker accepted");});
        Test("legacy-incomplete-restore-blocked-until-acknowledged",dir=>{var f=Family(dir);f.Parent.OmittedFolders.Add("engine");var e=new BackupEngine(Path.Combine(dir,"backup"));var job=e.CreateAsync(f.Parent,[]).GetAwaiter().GetResult();job.Package.CandidateOmissions.Add("engine");File.WriteAllText(Path.Combine(e.Root,job.Id,"manifest.json"),JsonSerializer.Serialize(job));var target=Path.Combine(dir,"restored");Refusal(()=>e.RestoreAsync(job.Id,target).GetAwaiter().GetResult());Check(!Directory.Exists(target),"Restore wrote before acknowledgement");var restore=e.RestoreAsync(job.Id,target,acknowledgeIncomplete:true).GetAwaiter().GetResult();Check(restore.Status=="Completed"&&restore.IncompleteScopeAccepted&&Directory.GetFiles(target,"Main.exe",SearchOption.AllDirectories).Length==1&&Directory.GetFiles(target,"required.dat",SearchOption.AllDirectories).Length==0,"Explicit partial restore failed");Check(new WorkHistoryStore(Path.Combine(dir,"history.json")).Refresh([e.Root]).Records.Any(r=>r.Kind=="Restore"&&r.PartialCoverage&&r.Attention),"Partial restore warning missing from history");});
        Test("new-backup-includes-nested-dependency-and-normal-restore",dir=>{var f=Family(dir);var e=new BackupEngine(Path.Combine(dir,"backup"));var job=e.CreateAsync(f.Parent,[]).GetAwaiter().GetResult();Check(!job.LegacyIncomplete&&job.Files.Any(f=>f.RelativePath.Contains("required.dat")),"Dependency absent");var restore=e.RestoreAsync(job.Id,Path.Combine(dir,"restored")).GetAwaiter().GetResult();Check(restore.Status=="Completed"&&!restore.IncompleteScopeAccepted,"Normal restore needs extra acknowledgement");});
        Test("unknown-scope-refuses-direct-move-without-touching-files",dir=>{var f=Family(dir);f.Parent.ScopeReviewRequired=true;var e=new BackupEngine(Path.Combine(dir,"records"));Refusal(()=>e.PrepareDirectMoveAsync(f.Parent,[]).GetAwaiter().GetResult());Check(File.Exists(Path.Combine(f.Parent.Source,"Main.exe"))&&!Directory.Exists(Path.Combine(dir,"target")),"Unknown scope changed files");});
        Test("interrupted-legacy-restore-requires-acknowledgement-on-resume",dir=>{var f=Family(dir);f.Parent.OmittedFolders.Add("engine");var e=new BackupEngine(Path.Combine(dir,"backup"));var job=e.CreateAsync(f.Parent,[]).GetAwaiter().GetResult();typeof(BackupEngine).GetProperty("Checkpoint",BindingFlags.Instance|BindingFlags.NonPublic)!.SetValue(e,(Action<string>)(phase=>{if(phase=="restore-file-committed")throw new IOException("generated interruption");}));Refusal(()=>e.RestoreAsync(job.Id,Path.Combine(dir,"restored")).GetAwaiter().GetResult());job.Package.CandidateOmissions.Add("engine");File.WriteAllText(Path.Combine(e.Root,job.Id,"manifest.json"),JsonSerializer.Serialize(job));var records=Directory.GetFiles(Path.Combine(e.Root,job.Id,"restores"),"*.json");var restore=JsonSerializer.Deserialize<RestoreJob>(File.ReadAllText(records.Single()))!;var fresh=new BackupEngine(e.Root);Refusal(()=>fresh.ResumeRestoreAsync(job.Id,restore.Id).GetAwaiter().GetResult());var result=fresh.ResumeRestoreAsync(job.Id,restore.Id,acknowledgeIncomplete:true).GetAwaiter().GetResult();Check(result.Status=="Completed"&&result.IncompleteScopeAccepted,"Resume ignored old incomplete scope");});
        var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var styles=XDocument.Load(Path.Combine(AppContext.BaseDirectory,"styles-source.xaml")).Root!.Elements().Single().Elements().Single();app.Resources=(ResourceDictionary)XamlReader.Parse(styles.ToString(),new ParserContext{BaseUri=new Uri(AppContext.BaseDirectory)});SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext());
        Test("scope-confirm-cancel-keeps-unknown-state",dir=>{var w=Window(dir,out var p);try{p.ScopeReviewRequired=true;p.ReviewState="scope";var before=File.ReadAllBytes(Path.Combine(dir,"data","workspace.json"));Application.Current.Dispatcher.BeginInvoke(new Action(()=>{var dialog=Application.Current.Windows.OfType<AppDialog>().Last();Layout(dialog,600,440,Path.Combine(root,"scope-confirm.png"));Check(dialog.ActionButtons.All(b=>b.Focusable),"Button not keyboard focusable");dialog.Close();}),DispatcherPriority.Background);Check(!(bool)Call(w,"ConfirmStoredScope",p)!&&p.ScopeReviewRequired,"Cancel accepted unknown scope");Check(before.SequenceEqual(File.ReadAllBytes(Path.Combine(dir,"data","workspace.json"))),"Cancel wrote workspace");}finally{Close(w);}});
        Test("scope-confirm-saves-explicit-current-scope",dir=>{var w=Window(dir,out var p);try{p.ScopeReviewRequired=true;p.ReviewState="scope";Application.Current.Dispatcher.BeginInvoke(new Action(()=>Click(Application.Current.Windows.OfType<AppDialog>().Last().ActionButtons.Last())),DispatcherPriority.Background);Check((bool)Call(w,"ConfirmStoredScope",p)!,"Explicit confirmation failed");var saved=Get<WorkspaceStore>(w,"workspaceStore").Load().Document!.Packages.Single();Check(!saved.ScopeReviewRequired&&!Get<List<Package>>(w,"packages").Single().ScopeReviewRequired,"Confirmed state not persisted");}finally{Close(w);}});
        Test("legacy-restore-dialog-cancel-and-acknowledge",dir=>{var w=Window(dir,out var p);try{var job=new BackupJob{Package=new(){CandidateOmissions=["engine"],OmittedFolders=["engine"]}};Application.Current.Dispatcher.BeginInvoke(new Action(()=>{var d=Application.Current.Windows.OfType<AppDialog>().Last();foreach(var expander in Logical((DependencyObject)d.Content).OfType<Expander>())expander.IsExpanded=true;Layout(d,600,480,Path.Combine(root,"legacy-restore-warning.png"));Check(Logical((DependencyObject)d.Content).OfType<TextBlock>().Any(t=>t.Text=="백업에 있는 파일만 복원"),"Partial action unclear");d.Close();}),DispatcherPriority.Background);Check(!(bool)Call(w,"ConfirmLegacyRestore",job)!,"Cancel approved partial restore");Application.Current.Dispatcher.BeginInvoke(new Action(()=>Click(Application.Current.Windows.OfType<AppDialog>().Last().ActionButtons.Last())),DispatcherPriority.Background);Check((bool)Call(w,"ConfirmLegacyRestore",job)!,"Explicit partial restore not accepted");Check(!(bool)Call(w,"ConfirmLegacyRestore",new BackupJob())!,"Normal backup prompts");}finally{Close(w);}});
        Test("legacy-warning-history-layout",dir=>{var w=Window(dir,out _);try{Set(w,"workHistory",new WorkHistoryDocument{Records=[new(){Root=Path.Combine(dir,"backup"),Kind="Restore",Title="가상 게임",State="Completed",Availability="Connected",PartialCoverage=true,UpdatedUtc=DateTime.UtcNow}]});Call(w,"SetPage","jobs");Call(w,"PaintHistory");Layout(w,1100,800,Path.Combine(root,"legacy-history.png"));Check(Logical((DependencyObject)w.Content).OfType<TextBlock>().Any(t=>t.Text.Contains("일부 폴더 복원")),"Partial history not shown");Check(Logical((DependencyObject)w.Content).OfType<TextBlock>().Any(t=>t.Text=="일부 복원 완료"),"Restore mislabeled as backup completion");}finally{Close(w);}});
        File.WriteAllText(args[1],JsonSerializer.Serialize(new{total=results.Count,passed=results.Count-failed,failed,results},new JsonSerializerOptions{WriteIndented=true}));return failed==0?0:1;
    }
}

